#include <bits/stdc++.h>
using namespace std;
#define ll long long
int main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        ll int n;
        cin>>n;
        vector<ll> a(3*n);
        for(auto &i: a) cin>>i;
        ll ans=0, m=3*n;
        sort(a.rbegin(),a.rend());
        vector<ll> ord(m+1,0);
        for(ll int i=0;i<m;i++){
            ord[i+1]=ord[i]+a[i];
        }
        for(ll int i=0;i<=2*n;i++){
            ll int y1 = max((ll)0,i-n);
            ll int y2 = i/2;
            ll int x1=y1,x2=y2;
            while(x1<x2){
                ll int z = (x1+x2)/2;
                ll int seq2 = (2*i)-(3*z);
                ll d = 2*a[z] - a[seq2-3] - a[seq2-2] - a[seq2-1];
                if(d>0) x1 = z+1;
                else x2 = z;
            }
            vector<ll int> c={x1, max(y1,x1-1), min(y2,x1+1)};
            for(ll int &j : c){
                ll int seq3 = (2*i) - (3*j);
                ll curr = ((ll)3 * ord[m-i]) + ((ll)2 * ord[j]) + (ord[seq3]);
                ans = max(ans,curr);
            }
        }
        cout<<ans<<endl;
    }
}
